{
  "prose": [
    {
      "key": "headline",
      "text": "Trade lower persona consistency for reduced serving costs with {arm:f64}, or retain {arm:prod} to preserve character fidelity."
    },
    {
      "key": "lede",
      "text": "{arm:f64} reduces reply expense from {cost_per_1k.prod|usd} to {cost_per_1k.f64|usd} per thousand while {judged.persona.prod} degrades to {judged.persona.f64} on {aspects.persona.name}. Adopting it depends on whether the team accepts fidelity degradation in conversations beyond turn {strata.depth:3-5.name}."
    },
    {
      "key": "flag.title",
      "text": "No Decision Rule Set in Advance"
    },
    {
      "key": "flag.text",
      "text": "No exchange rate between reply cost and persona adherence was set ahead of time. Product leadership must determine whether unit savings justify character loss."
    },
    {
      "key": "decision.the_trade",
      "text": "Switching to {arm:f64} trims costs by thirty percent but drops {aspects.persona.name} by {contrast.f64.persona.delta|abs|pts} points ({contrast.f64.persona.interval|pts}), while keeping guardrails intact."
    },
    {
      "key": "decision.where_it_flips",
      "text": "Choose {arm:f64} if saving ten cents per thousand replies justifies losing one point of persona adherence. Retain {arm:prod} if persona degradation must remain below five points."
    },
    {
      "key": "decision.our_lean",
      "text": "Lean toward {arm:f64} if overall cost reduction is prioritized and conversations concentrate in early turns."
    },
    {
      "key": "decision.what_settles_it",
      "text": "Human preference trials on extended conversations or setting an explicit minimum threshold for {aspects.persona.name} at depth {strata.depth:6-10.name}."
    },
    {
      "key": "summary.0.title",
      "text": "Cost per 1,000 replies"
    },
    {
      "key": "summary.1.title",
      "text": "Stays in character adherence"
    },
    {
      "key": "sections.contrasts_spine.eyebrow",
      "text": "Persona Adherence Delta"
    },
    {
      "key": "sections.contrasts_spine.headline",
      "text": "All challenger models regress on character consistency relative to production"
    },
    {
      "key": "sections.contrasts_spine.takeaway",
      "text": "{arm:cor} drops the least at {contrast.cor.persona.delta|pts} points, while {arm:f16} shows the steepest drop at {contrast.f16.persona.delta|pts} points."
    },
    {
      "key": "sections.contrasts_spine.title",
      "text": ""
    },
    {
      "key": "sections.contrasts_spine.caption",
      "text": "{family.disclosure}"
    },
    {
      "key": "sections.depth_divergence.eyebrow",
      "text": "Conversation Depth Impact"
    },
    {
      "key": "sections.depth_divergence.headline",
      "text": "Character fidelity decays sharply at deeper turns for Flash models"
    },
    {
      "key": "sections.depth_divergence.takeaway",
      "text": "At turns {strata.depth:11+.name}, {arm:f64} drops to {strata.depth:11+.per_arm.f64.persona.mean|pct} compared to {strata.depth:11+.per_arm.prod.persona.mean|pct} for {arm:prod}."
    },
    {
      "key": "sections.depth_divergence.title",
      "text": ""
    },
    {
      "key": "sections.depth_divergence.caption",
      "text": ""
    },
    {
      "key": "sections.scenario_breakdown.eyebrow",
      "text": "Scenario Robustness"
    },
    {
      "key": "sections.scenario_breakdown.headline",
      "text": "Taking corrections and banter drive the largest drops in persona"
    },
    {
      "key": "sections.scenario_breakdown.takeaway",
      "text": "Across all models, song intros remain stable while handling user corrections causes severe persona decay."
    },
    {
      "key": "sections.scenario_breakdown.title",
      "text": ""
    },
    {
      "key": "sections.scenario_breakdown.caption",
      "text": ""
    },
    {
      "key": "durable_claims.0",
      "text": "{arm:f64} reduces cost from {cost_per_1k.prod|usd} to {cost_per_1k.f64|usd} per thousand replies while lowering persona compliance from {judged.persona.prod} to {judged.persona.f64} ({contrast.f64.persona.delta|pts} points)."
    },
    {
      "key": "durable_claims.1",
      "text": "{arm:cor} breaches the {criteria.specul.label} guardrail threshold of {criteria.specul.threshold|pct}, falling to {measure.specul.cor.mean|pct} ({contrast.cor.specul.delta|pts} points)."
    },
    {
      "key": "method.0.term",
      "text": "Cases and repeats"
    },
    {
      "key": "method.0.text",
      "text": "Evaluated across {scoreboard.prod.cases} dialogue scenarios run across multi-turn sessions totaling {scoreboard.prod.ran} responses per arm."
    },
    {
      "key": "method.1.term",
      "text": "Judge tier"
    },
    {
      "key": "method.1.text",
      "text": "{aspects.persona.name} assessed by a calibrated model judge validated on {judged.persona.calibration_ratings} human comparisons with agreement score {judged.persona.agreement}."
    },
    {
      "key": "method.2.term",
      "text": "Guardrails"
    },
    {
      "key": "method.2.text",
      "text": "Music facts evaluated against catalog truth (pass at {criteria.facts.threshold|pct}); speculation refusal evaluated on bait prompts (pass at {criteria.specul.threshold|pct})."
    },
    {
      "key": "method.3.term",
      "text": "Inference cost basis"
    },
    {
      "key": "method.3.text",
      "text": "Calculated using token usage multiplied by standard list pricing per thousand queries, accounting for increasing context length."
    },
    {
      "key": "method.4.term",
      "text": "Inference intervals"
    },
    {
      "key": "method.4.text",
      "text": "{family.level} paired differences against control without multiplicity correction across challengers."
    },
    {
      "key": "method.5.term",
      "text": "Tool invocation check"
    },
    {
      "key": "method.5.text",
      "text": "Deterministic programmatic validation checking whether queue, skip, or announce actions execute properly."
    },
    {
      "key": "explore.title",
      "text": "Explore Valuation Tradeoffs"
    },
    {
      "key": "explore.recomputes",
      "text": "Adjusting valuation per point recalculates preferred configurations; values below ten cents favor {arm:f64}, while higher values retain {arm:prod}."
    },
    {
      "key": "explore.controls.price_per_point.title",
      "text": "Willingness to pay per persona point ($/1k)"
    }
  ]
}

